package com.example.starter.web.dto;

import java.math.BigDecimal;
import java.time.Instant;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 建窗请求。起止时刻为 UTC（ISO-8601），窗口为半开区间 [startAt, endAt)。
 */
public record CreateWindowRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 128) String vesselName,
        @NotNull Long berthId,
        @NotNull Instant startAt,
        @NotNull Instant endAt,
        @NotNull @DecimalMin(value = "0.0", inclusive = false) @Digits(integer = 4, fraction = 2) BigDecimal draftM,
        @Min(1) @Max(16) int pilotsRequired) {
}

package com.example.starter.web.dto;

import java.time.Instant;

import jakarta.validation.constraints.NotNull;

/**
 * 改期请求：新的预计靠泊起止时刻（UTC，半开区间）。
 */
public record RescheduleRequest(
        @NotNull Instant startAt,
        @NotNull Instant endAt) {
}

package com.example.starter.web.dto;

import java.time.Instant;
import java.util.List;

import com.example.starter.domain.BerthWindow;

/**
 * 窗口响应。时间均为 UTC ISO-8601。
 */
public record WindowResponse(
        long id,
        String requestId,
        String vesselName,
        long berthId,
        Instant startAt,
        Instant endAt,
        double draftM,
        int pilotsRequired,
        String status,
        List<Long> pilotIds,
        Instant createdAt,
